// ME Pro — validate & authenticate
// Set this to the same string as the Pine input "Webhook Shared Secret".
// Leave '' only if you also left the Pine field empty (endpoint is then open).
const EXPECTED_SECRET = '';

const out = [];
for (const item of $input.all()) {
  let p = item.json.body ?? item.json;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); }
    catch (e) { throw new Error('Payload is not valid JSON: ' + e.message); }
  }

  if (EXPECTED_SECRET !== '') {
    if (p.secret !== EXPECTED_SECRET) throw new Error('Rejected: bad or missing secret');
  }

  const required = ['action','symbol','tf','entry','sl','tp1','tp2','tp3','seq','bar_time'];
  const missing = required.filter(k => p[k] === undefined || p[k] === null || p[k] === '');
  if (missing.length) throw new Error('Missing fields: ' + missing.join(', '));

  if (p.action !== 'BUY' && p.action !== 'SELL') throw new Error('Bad action: ' + p.action);

  for (const k of ['entry','sl','tp1','tp2','tp3','risk_atr','confluence','seq','bar_time','rsi','delta','rel_vol']) {
    if (p[k] !== undefined) {
      const v = Number(p[k]);
      if (!isFinite(v)) throw new Error('Non-numeric field ' + k + ': ' + p[k]);
      p[k] = v;
    }
  }

  // Direction sanity — catches a malformed or spoofed payload that would
  // otherwise place a stop on the wrong side of entry.
  if (p.action === 'BUY'  && !(p.sl < p.entry)) throw new Error('BUY with SL at/above entry');
  if (p.action === 'SELL' && !(p.sl > p.entry)) throw new Error('SELL with SL at/below entry');

  delete p.secret;
  p.received_at = new Date().toISOString();
  out.push({ json: p });
}
return out;

// ME Pro — drop duplicate deliveries
// TradingView can retry a webhook, and the engine re-sends nothing, so any
// repeat of the same (symbol, tf, mode, seq, bar_time) is a duplicate.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const now = Date.now();
const TTL_MS = 7 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(store.seen)) {
  if (now - store.seen[k] > TTL_MS) delete store.seen[k];
}

const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const key = [p.symbol, p.tf, p.mode, p.seq, p.bar_time].join('|');
  if (store.seen[key]) continue;
  store.seen[key] = now;
  out.push(item);
}
return out;

// ME Pro — quality gate. Everything here is a policy choice, not engine logic;
// tune it without touching Pine. Items are never dropped, only flagged, so
// rejects stay visible in the execution log.
const CFG = {
  minConfluence:          2,      // 0-3 (HTF side + VWAP side + value-area side)
  requireStructuralStop:  true,   // reject stop_type === 'clamped'
  allowedModes:           [],     // [] = any. e.g. ['Balanced','Strict']
  allowedTriggers:        [],     // [] = any. e.g. ['MSS','SWEEP']
  minRiskAtr:             0.0,
  maxRiskAtr:             99.0,
  minRR1:                 1.0,    // TP1 distance as a multiple of stop distance
};

const out = [];
for (const item of $input.all()) {
  const p = { ...item.json };
  const risk = Math.abs(p.entry - p.sl);
  const rr1  = risk > 0 ? Math.abs(p.tp1 - p.entry) / risk : 0;
  const why  = [];

  if (p.confluence !== undefined && p.confluence < CFG.minConfluence) why.push('confluence ' + p.confluence + '<' + CFG.minConfluence);
  if (CFG.requireStructuralStop && p.stop_type === 'clamped')          why.push('stop is clamped, not structural');
  if (CFG.allowedModes.length    && !CFG.allowedModes.includes(p.mode))       why.push('mode ' + p.mode);
  if (CFG.allowedTriggers.length && !CFG.allowedTriggers.includes(p.trigger)) why.push('trigger ' + p.trigger);
  if (p.risk_atr !== undefined && (p.risk_atr < CFG.minRiskAtr || p.risk_atr > CFG.maxRiskAtr)) why.push('risk_atr ' + p.risk_atr);
  if (rr1 < CFG.minRR1) why.push('TP1 reward ' + rr1.toFixed(2) + 'R < ' + CFG.minRR1 + 'R');

  p.rr1 = Number(rr1.toFixed(2));
  p.risk_per_unit = risk;
  p.passed = why.length === 0;
  p.reject_reason = why.join('; ');
  out.push({ json: p });
}
return out;

// ME Pro — risk-normalised position size + a human-readable message.
// Size follows from stop distance, so a wide-stop trade takes a smaller
// position and every trade risks the same fraction of equity.
const ACCOUNT = {
  equity:  10000,   // set to your real account size, or fetch it upstream
  riskPct: 1.0,     // % of equity risked per trade
  qtyDecimals: 4,
};

const out = [];
for (const item of $input.all()) {
  const p = { ...item.json };
  const risk = p.risk_per_unit || Math.abs(p.entry - p.sl);
  const qty  = risk > 0 ? (ACCOUNT.equity * ACCOUNT.riskPct / 100) / risk : 0;

  p.qty            = Number(qty.toFixed(ACCOUNT.qtyDecimals));
  p.risk_amount    = Number((ACCOUNT.equity * ACCOUNT.riskPct / 100).toFixed(2));
  p.account_equity = ACCOUNT.equity;

  const arrow = p.action === 'BUY' ? 'LONG' : 'SHORT';
  p.message = [
    `${arrow} ${p.symbol} ${p.tf}m  (${p.mode} / ${p.trigger})`,
    `entry ${p.entry}   SL ${p.sl}  [${p.stop_type}]`,
    `TP1 ${p.tp1}   TP2 ${p.tp2}   TP3 ${p.tp3}`,
    `risk ${p.risk_atr}x ATR   TP1 = ${p.rr1}R   confluence ${p.confluence}/3`,
    `HTF ${p.htf}  VWAP ${p.vwap}  CVD ${p.cvd}  regime ${p.regime}`,
    `size ${p.qty} (risking ${p.risk_amount} of ${p.account_equity})`,
  ].join('\n');

  out.push({ json: p });
}
return out;
